diff --git a/lib/urlapi.c b/lib/urlapi.c
index a3111f9db6..0aedff97f8 100644
--- a/lib/urlapi.c
+++ b/lib/urlapi.c
@@ -489,20 +489,23 @@ static CURLUcode hostname_check(struct Curl_URL *u, char *hostname,
 /*
  * Handle partial IPv4 numerical addresses and different bases, like
  * '16843009', '0x7f', '0x7f.1' '0177.1.1.1' etc.
  *
  * If the given input string is syntactically wrong IPv4 or any part for
  * example is too big, this function returns HOST_NAME.
  *
  * Output the "normalized" version of that input string in plain quad decimal
  * integers.
  *
+ * A single dot following the numerical address is accepted and "swallowed" as
+ * if it was never there.
+ *
  * Returns the host type.
  *
  * @unittest 1675
  */

 UNITTEST int ipv4_normalize(struct dynbuf *host);
 UNITTEST int ipv4_normalize(struct dynbuf *host)
 {
   bool done = FALSE;
   int n = 0;
@@ -513,38 +516,49 @@ UNITTEST int ipv4_normalize(struct dynbuf *host)
   if(*c == '[')
     return HOST_IPV6;

   while(!done) {
     int rc;
     curl_off_t l;
     if(*c == '0') {
       if(c[1] == 'x') {
         c += 2; /* skip the prefix */
         rc = curlx_str_hex(&c, &l, UINT_MAX);
+        if(rc)
+          return HOST_NAME;
       }
       else
         rc = curlx_str_octal(&c, &l, UINT_MAX);
     }
     else
       rc = curlx_str_number(&c, &l, UINT_MAX);

-    if(rc)
-      return HOST_NAME;
-
-    parts[n] = (unsigned int)l;
+    if(rc) {
+      if(!n || (rc != STRE_NO_NUM) || *c)
+        return HOST_NAME;
+      n--;
+    }
+    else
+      parts[n] = (unsigned int)l;

     switch(*c) {
     case '.':
-      if(n == 3)
-        return HOST_NAME;
-      n++;
-      c++;
+      if(n == 3) {
+        if(c[1])
+          /* something follows this dot */
+          return HOST_NAME;
+        done = TRUE;
+      }
+      else {
+        n++;
+        c++;
+      }
       break;

     case '\0':
       done = TRUE;
       break;

     default:
       return HOST_NAME;
     }
   }

